#!/bin/sh
# First start of the bundle's database: the application role (no
# BYPASSRLS: row-level security backs every tenant predicate). Its password
# is generated by the gateway (hex, so it needs no quoting). The image creates
# the timescaledb extension in POSTGRES_DB itself.
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname signing <<SQL
CREATE ROLE signing_app LOGIN PASSWORD '${SIGNING_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE signing TO signing_app;
SQL
